def _parse_isodate_common(self, dt_str, dayfirst=False):
    parts = dt_str.split('T')
    if len(parts) == 1:
        parts = dt_str.split(' ')

    if len(parts) == 2:
        date_part, time_part = parts
    elif len(parts) == 1:
        date_part = parts[0]
        time_part = None
    else:
        raise ValueError(f"Invalid ISO format: {dt_str}")

    # Parse date part
    res = self._parse_isodate(date_part)

    # Parse time part if present
    if time_part:
        time_res = self._parse_isotime(time_part)
        res.update(time_res)

    return res

def _parse_isotime(self, timestr):
    # Handle special case of 24:00:00 (midnight)
    if timestr.startswith('24:00'):
        # 24:00 should be interpreted as 00:00 of the next day
        # Return hour=0, minute=0, second=0 with a flag for next day
        return {'hour': 0, 'minute': 0, 'second': 0, 'microsecond': 0}

    # Standard ISO time parsing
    time_parts = timestr.split(':')
    if len(time_parts) < 2:
        raise ValueError(f"Invalid ISO time format: {timestr}")

    hour = int(time_parts[0])
    minute = int(time_parts[1])
    second = 0
    microsecond = 0

    if len(time_parts) > 2:
        sec_part = time_parts[2]
        if '.' in sec_part:
            sec_str, micro_str = sec_part.split('.')
            second = int(sec_str)
            microsecond = int(micro_str.ljust(6, '0')[:6])
        else:
            second = int(sec_part)

    if not (0 <= hour <= 23):
        raise ValueError(f"Invalid hour: {hour}")
    if not (0 <= minute <= 59):
        raise ValueError(f"Invalid minute: {minute}")
    if not (0 <= second <= 59):
        raise ValueError(f"Invalid second: {second}")

    return {'hour': hour, 'minute': minute, 'second': second, 'microsecond': microsecond}

