def _parse_isotime(self, tstr):
    # This is adapted from the `parse_isotime` function in isoparser.py
    len_str = len(tstr)
    pos = 0
    comps = {}

    for i, key in enumerate(['hour', 'minute', 'second']):
        if i == 0:
            length = 2
        else:
            if pos < len_str and tstr[pos] == ':':
                pos += 1
            else:
                break
            length = 2

        if pos + length > len_str:
            break

        comps[key] = int(tstr[pos:pos+length])
        pos += length

        if i == 0:
            # Handle special case of 24:00:00 (midnight)
            if comps['hour'] == 24:
                if pos < len_str:
                    # There are more characters - check if they're all zeros
                    rest = tstr[pos:]
                    if rest.startswith(':'):
                        rest = rest[1:]
                    if rest.startswith('00'):
                        rest = rest[2:]
                    if rest.startswith(':'):
                        rest = rest[1:]
                    if rest.startswith('00'):
                        rest = rest[2:]
                    if rest:
                        # Not all zeros after 24:, invalid
                        raise ValueError('hour must be in 0..23')
                # 24:00:00 is valid - convert to 00:00:00 of next day
                comps['hour'] = 0
                comps['minute'] = 0
                comps['second'] = 0
                self._isotime_midnight = True
            elif comps['hour'] > 23:
                raise ValueError('hour must be in 0..23')

        if i == 1 and comps['minute'] > 59:
            raise ValueError('minute must be in 0..59')

        if i == 2 and comps['second'] > 59:
            raise ValueError('second must be in 0..59')

    return comps

