def _parse_hms(self, hour, minute, second, microsecond):
    """
    Parse hour, minute, second, microsecond.

    Special handling for hour=24 (ISO 8601 midnight representation).
    """
    # Handle ISO 8601 24:00:00 as midnight of next day
    if hour == 24:
        if minute != 0 or second != 0 or microsecond != 0:
            raise ValueError("Hour is 24, but minute, second, or microsecond is not zero")
        hour = 0
        return hour, minute, second, microsecond, 1  # Return day increment of 1

    if not 0 <= hour <= 23:
        raise ValueError('hour must be in 0..23')
    if not 0 <= minute <= 59:
        raise ValueError('minute must be in 0..59')
    if not 0 <= second <= 59:
        raise ValueError('second must be in 0..59')
    if not 0 <= microsecond <= 999999:
        raise ValueError('microsecond must be in 0..999999')

    return hour, minute, second, microsecond, 0  # Return day increment of 0

