def _parse_hms(self, h_str, m_str, s_str, ms_str, tzstr='', default=None):
    # Handling of ISO 8601 special case: 24:00 represents midnight
    h = self._to_integer(h_str)
    if h == 24:
        if m_str or s_str or ms_str:
            # 24:00:00 is valid, but 24:00:01 or 24:mm:ss (m,s != 0) is invalid
            if self._to_integer(m_str or 0) != 0 or self._to_integer(s_str or 0) != 0 or self._to_integer(ms_str or 0) != 0:
                raise ValueError("hour must be in 0..23")
        h = 0
    elif h > 23:
        raise ValueError("hour must be in 0..23")

    m = self._to_integer(m_str or 0)
    if m > 59:
        raise ValueError("minute must be in 0..59")

    s = self._to_integer(s_str or 0)
    if s > 59:
        raise ValueError("second must be in 0..59")

    ms = int(Decimal(ms_str or 0) * 1e6)

    if tzstr:
        tzinfo = self._parse_tzstr(tzstr, default=default)
    else:
        tzinfo = None

    return datetime.time(hour=h, minute=m, second=s, microsecond=ms, tzinfo=tzinfo)

