    except AttributeError:
        # Python 2/3 compatibility
        l = list(_timelex(timestr))

    mstridx = None
    for i, token in enumerate(l):
        # Skip empty tokens
        if not token or token.isspace():
            continue

        try:
            # Numeric token
            try:
                value = int(token)
            except ValueError:
                try:
                    value = float(token)
                except ValueError:
                    # Not a number, must be a word
                    value = None

            if value is not None:
                # Handle numbers
                try:
                    res, tokens_consumed = self._parse_numeric(
                        tokens=l, idx=i, res=res, fuzzy=fuzzy)
                except ValueError:
