    if res.hour == 24:
        if res.minute != 0 or res.second != 0 or res.microsecond != 0:
            raise ValueError("hour=24 is only valid with 00:00:00")
        # Roll over to next day at 00:00
        res.hour = 0
        if res.day is not None and res.month is not None and res.year is not None:
            # Increment the date by one day
            dt = datetime.datetime(res.year, res.month, res.day,
